/* 组件就绪后执行 */
Eam.registerInit(async function(){
/* 保养详情表单绑定；业务状态仅由模拟接口命令改变。 */
await (async()=>{if(!document.getElementById('pm-form'))return;const $=id=>document.getElementById(id),api=EamMaintenanceApi,query=new URLSearchParams(location.search),labels={draft:'草稿',pending_review:'待审核',published:'已发布',paused:'已暂停',terminated:'已终止'},names={submit:'提交审核',approve:'批准发布',reject:'退回修改',pause:'暂停计划',resume:'恢复计划',terminate:'终止计划',revise:'创建修订草稿'};let record,config,id=query.get('id'),busy=false,command,dirty=false,preview=[],previewPage=1,selected=new Set(),generationKey;const createKey=crypto.randomUUID();
function item(row={name:'',part:'',method:'',criterion:'',resultType:'conclusion',unit:'',min:'',max:'',required:true,evidenceRequired:true}){const node=$('pm-item-template').content.firstElementChild.cloneNode(true);for(const control of node.querySelectorAll('[data-field]')){const v=row[control.dataset.field];if(control.type==='checkbox')control.checked=!!v;else control.value=v??'';}node.querySelector('[data-remove-item]').onclick=()=>{node.remove();dirty=true;};$('pm-items').append(node);}
function bind(){query.set('equipment',record.equipmentId);for(const [key,value] of Object.entries({name:record.name,device:record.equipmentId,org:record.organization,cycle:record.unit,interval:record.interval,anchor:record.anchorDate,before:record.windowBefore,after:record.windowAfter,mode:record.assignmentMode,primary:record.primaryPersonId,'valid-from':record.assignmentValidFrom,'valid-to':record.assignmentValidTo}))$('pm-'+key).value=value??'';for(const checkbox of $('pm-bindings').querySelectorAll('input'))checkbox.checked=record.bindings.some(b=>b.type===checkbox.dataset.type&&b.id===checkbox.value);$('pm-items').replaceChildren();record.items.forEach(item);$('pm-state').textContent=labels[record.status];$('pm-title').textContent=id?record.name:'新增保养计划';$('pm-version').textContent=(record.code||'编号保存后生成')+' · 计划V'+record.planVersion+' · 数据V'+record.revision+(record.activeVersion?' · 有效版本V'+record.activeVersion+'（'+labels[record.activeStatus||'published']+'）':'');$('pm-fields').disabled=!record.actions.edit;$('pm-save').hidden=!record.actions.edit;$('pm-add-item').hidden=!record.actions.edit;$('pm-actions').replaceChildren();for(const [action,label]of Object.entries(names))if(record.actions[action]){const button=document.createElement('button');button.type='button';button.className='btn btn-sm '+(action==='approve'?'btn-primary':'btn-outline-secondary');button.textContent=label;button.onclick=()=>{if(dirty){Eam.message('请先保存草稿，再执行状态操作');return;}command=action;$('pm-command-title').textContent=label;$('pm-command-context').textContent=record.code+' · V'+record.planVersion+' · 提交人 '+(record.submittedBy||'尚未提交')+'；审核不得由提交人本人执行';$('pm-command-form').reset();$('pm-command-error').textContent='';$('pm-command-dialog').showModal();};$('pm-actions').append(button);}$('pm-history').replaceChildren();for(const version of record.versions||[]){const p=document.createElement('p');p.textContent='发布快照V'+version.planVersion+' · '+version.name+' · '+version.items.length+'项 · 批准人 '+version.approvedBy;$('pm-history').append(p);}for(const a of record.audit||[]){const p=document.createElement('p');p.textContent=EamProduct.time(a.at)+' · '+a.actorId+' · '+(names[a.action]||'保存草稿')+' · '+a.reason;$('pm-history').append(p);}if(!$('pm-history').children.length)$('pm-history').textContent='暂无审核及版本记录';$('pm-generate').hidden=!record.actions.generate;$('pm-preview').disabled=!record.actions.preview;$('pm-preview-load').textContent=record.actions.preview?'使用已发布V'+(record.activeVersion||record.planVersion)+'；预览不生成任务':'当前没有可预览的有效发布版本';$('pm-error').textContent='';$('pm-detail-load').textContent='已读取计划 · 数据V'+record.revision;dirty=false;}
async function load(){try{if(id){record=await api.request('GET','/maintenance/plans/'+encodeURIComponent(id));const scope=query.get('equipment');if(scope&&record.equipmentId!==scope)throw new Error('计划不属于当前设备范围');}else{record={...config.draft,equipmentId:query.get('equipment')||config.draft.equipmentId,actions:{edit:config.canCreate}};}bind();preview=[];drawPreview();}catch(e){$('pm-detail-load').textContent=e.message;$('pm-fields').disabled=true;$('pm-save').hidden=true;$('pm-actions').replaceChildren();$('pm-preview').disabled=true;}}
function payload(){return {name:$('pm-name').value,equipmentId:$('pm-device').value,organization:$('pm-org').value,unit:$('pm-cycle').value,interval:Number($('pm-interval').value),anchorDate:$('pm-anchor').value,windowBefore:Number($('pm-before').value),windowAfter:Number($('pm-after').value),timezone:config.timezone,assignmentMode:$('pm-mode').value,primaryPersonId:$('pm-primary').value,assignmentValidFrom:$('pm-valid-from').value,assignmentValidTo:$('pm-valid-to').value,bindings:[...$('pm-bindings').querySelectorAll('input:checked')].map(x=>({type:x.dataset.type,id:x.value})),items:[...$('pm-items').children].map((node,i)=>Object.fromEntries([['id','MI-'+(i+1)],...[...node.querySelectorAll('[data-field]')].map(x=>[x.dataset.field,x.type==='checkbox'?x.checked:x.value])]))};}
$('pm-form').addEventListener('input',()=>dirty=true);$('pm-form').addEventListener('change',()=>dirty=true);$('pm-add-item').onclick=()=>{item();dirty=true;};$('pm-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;$('pm-save').disabled=true;try{const body={...payload(),expectedRevision:record.revision,idempotencyKey:createKey};record=await api.request(id?'PATCH':'POST','/maintenance/plans'+(id?'/'+encodeURIComponent(id):''),body);id=record.id;const url=new URL(location.href);url.searchParams.set('id',id);url.searchParams.delete('create');if(url.searchParams.get('returnEquipment')&&url.searchParams.get('returnEquipment')!==record.equipmentId){url.searchParams.set('equipment',record.equipmentId);url.searchParams.delete('returnEquipment');url.searchParams.delete('returnTab');}url.searchParams.set('equipment',record.equipmentId);if(!url.searchParams.get('returnEquipment'))document.querySelector('[data-component=equipment-context]')?.remove();history.replaceState(null,'',url);bind();Eam.message('草稿已保存');}catch(error){$('pm-error').textContent=error.message+'；输入已保留';}finally{busy=false;$('pm-save').disabled=false;}};
$('pm-reload').onclick=()=>{if(dirty&&!confirm('重新读取将放弃未保存输入，是否继续？'))return;load();};$('pm-command-cancel').onclick=()=>$('pm-command-dialog').close();$('pm-command-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;$('pm-command-submit').disabled=true;try{record=await api.request('POST','/maintenance/plans/'+encodeURIComponent(id)+'/'+command,{expectedRevision:record.revision,reason:$('pm-reason').value});$('pm-command-dialog').close();bind();preview=[];drawPreview();}catch(error){$('pm-command-error').textContent=error.message+'；意见已保留';}finally{busy=false;$('pm-command-submit').disabled=false;}};
function drawPreview(){const body=$('pm-preview-rows');body.replaceChildren();for(const row of preview.slice((previewPage-1)*8,previewPage*8)){const tr=document.createElement('tr'),td=document.createElement('td'),check=document.createElement('input');check.type='checkbox';check.className='form-check-input';check.setAttribute('aria-label','选择 '+row.scheduledAt);check.checked=selected.has(row.windowKey);check.disabled=!row.reason.startsWith('可计划')||!record.actions.generate;check.onchange=()=>check.checked?selected.add(row.windowKey):selected.delete(row.windowKey);td.append(check);tr.append(td);for(const value of [row.scheduledAt,row.windowStart+' 至 '+row.windowEnd,'V'+row.planVersion,row.reason]){const td=document.createElement('td');td.textContent=value;tr.append(td);}body.append(tr);}EamUiComponents.decorateTables();EamUiComponents.setTableStatus('pm-preview-rows','loaded');EamUiComponents.pagination($('pm-preview-pagination'),{page:previewPage,pages:Math.max(1,Math.ceil(preview.length/8)),total:preview.length,pageSize:8,onChange:p=>{previewPage=p;drawPreview();}});}
$('pm-preview').onclick=async()=>{const b=$('pm-preview');b.disabled=true;EamUiComponents.setTableStatus('pm-preview-rows','loading');try{const data=await api.request('GET','/maintenance/plans/'+encodeURIComponent(id)+'/generation-preview?'+new URLSearchParams({from:$('pm-from').value,to:$('pm-to').value}));preview=data.items;selected.clear();previewPage=1;drawPreview();$('pm-preview-load').textContent='预览'+data.total+'个窗口 · 未生成任务 · '+data.timezone;}catch(e){$('pm-preview-load').textContent=e.message;EamUiComponents.setTableStatus('pm-preview-rows','error',e.message,()=>$('pm-preview').click());}finally{b.disabled=!record?.actions.preview;}};
$('pm-generate').onclick=()=>{if(dirty){Eam.message('请先保存草稿');return;}if(!selected.size){Eam.message('请勾选需要生成的窗口');return;}generationKey=crypto.randomUUID();$('pm-generate-form').reset();$('pm-generate-error').textContent='';$('pm-generate-reason').required=preview.some(w=>selected.has(w.windowKey)&&w.scheduledAt<config.asOfDate);$('pm-generate-context').textContent='使用已发布V'+record.activeVersion+'，选中'+selected.size+'个窗口；已生成窗口返回原任务。';$('pm-generate-dialog').showModal();};$('pm-generate-cancel').onclick=()=>$('pm-generate-dialog').close();$('pm-generate-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;$('pm-generate-submit').disabled=true;try{const data=await api.request('POST','/maintenance/plans/'+encodeURIComponent(id)+'/generate',{activeVersion:record.activeVersion,expectedRevision:record.revision,windowKeys:[...selected],reason:$('pm-generate-reason').value,idempotencyKey:generationKey});$('pm-generated-results').replaceChildren();for(const row of data.items){const button=document.createElement('button');button.type='button';button.className='btn btn-sm btn-outline-primary me-2 mb-1';button.textContent=(row.result==='created'?'已生成 ':'已有任务 ')+row.taskId;button.onclick=()=>Eam.go('maintenance-task',{id:row.taskId,equipment:record.equipmentId});$('pm-generated-results').append(button);}$('pm-generate-dialog').close();selected.clear();drawPreview();}catch(error){$('pm-generate-error').textContent=error.message+'；选择与原因已保留';}finally{busy=false;$('pm-generate-submit').disabled=false;}};
try{config=await api.request('GET','/maintenance/config');for(const e of config.equipment)$('pm-device').add(new Option(e.name,e.id));$('pm-primary').add(new Option('请选择主责',''));for(const p of config.people)$('pm-primary').add(new Option(p.name,p.id));for(const [type,rows]of [['position',config.positions],['person',config.people]])for(const row of rows){const label=document.createElement('label');label.className='form-check';const box=document.createElement('input');box.type='checkbox';box.className='form-check-input';box.dataset.type=type;box.value=row.id;label.append(box,document.createTextNode((type==='position'?'岗位：':'人员：')+row.name));$('pm-bindings').append(label);}$('pm-from').value=config.previewFrom;$('pm-to').value=config.previewTo;await load();}catch(e){$('pm-detail-load').textContent=e.message;$('pm-fields').disabled=true;$('pm-save').hidden=true;$('pm-preview').disabled=true;}})();

});
